const BY_TIER = { 1: [], 2: [], 3: [] };
ENDLESS.forEach((e) => { (BY_TIER[e.tier] || BY_TIER[3]).push(e); });

function buildGrid(e) {
  let rows = 0;
  for (const k in e.F) rows = Math.max(rows, Number(k.split('-')[0]) + 1);
  for (const a of e.art) rows = Math.max(rows, a[0] + 1);
  const g = Array.from({ length: rows }, () => new Array(e.cols).fill(null));
  for (const k in e.F) { const [r, c] = k.split('-').map(Number); const cell = e.F[k]; g[r][c] = { value: cell.v, color: e.colors.P, clueIds: cell.ids }; }
  for (const a of e.art) { g[a[0]][a[1]] = { art: true, color: e.colors[a[2]] || e.colors.P }; }
  return g;
}

export function tierForLevel(level) { return level <= 4 ? 1 : level <= 10 ? 2 : 3; }
export function difficultyLabel(level) { return { 1: 'Kolay', 2: 'Orta', 3: 'Zor' }[tierForLevel(level)]; }

export function getEndlessPuzzle(level) {
  const pool = BY_TIER[tierForLevel(level)];
  const e = pool[Math.floor(Math.random() * pool.length)];
  return { kind: 'grid', name: 'Seviye ' + level, grid: buildGrid(e), clues: e.clues, endless: true, wc: e.wc };
}

export function endlessCount() { return ENDLESS.length; }
